parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "topic_supported": {
      "type": "boolean",
      "description": "True only if at least one retrieved source discusses the topic as stated (by name, if the topic names something specific). False if you found only related but different material."
    },
    "findings": {
      "type": "array",
      "description": "Findings about the topic as stated. Must be empty if topic_supported is false.",
      "items": {
        "type": "object",
        "properties": {
          "claim": {
            "type": "string",
            "description": "One specific claim that a retrieved source explicitly makes."
          },
          "detail": {
            "type": "string",
            "description": "Context for the claim, based only on the source. No speculation."
          },
          "evidence": {
            "type": "string",
            "description": "A short excerpt (under 25 words) copied from the search results that directly supports the claim."
          },
          "source_url": {
            "type": "string",
            "description": "The URL of the page the evidence came from."
          }
        },
        "required": ["claim", "detail", "evidence", "source_url"]
      }
    },
    "gaps": {
      "type": "array",
      "description": "What the brief needs that you could not find reliable support for, stated plainly (e.g. 'No source found that mentions X').",
      "items": { "type": "string" }
    },
    "confidence": {
      "type": "string",
      "enum": ["low", "medium", "high"],
      "description": "Confidence in support for the topic itself, not for adjacent material. Must be low if topic_supported is false."
    }
  },
  "required": ["topic_supported", "findings", "gaps", "confidence"]
}

parameters.jsCode:
const item = $input.first().json;
const out = item.output;
const steps = item.intermediateSteps || [];

// Ignore case, punctuation and spacing so formatting can't cause false mismatches
const norm = s => String(s ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

const raw = steps
  .map(s => typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation))
  .join(' ');
const corpus = norm(raw);

const verified = (out.findings || []).filter(f => {
  const ev = norm(f.evidence);
  return ev.length >= 20 && corpus.includes(ev) && raw.includes(f.source_url);
});

const dropped = (out.findings || []).length - verified.length;
const gaps = [...(out.gaps || [])];
if (dropped > 0) {
  gaps.push(`${dropped} finding(s) removed: evidence not found in retrieved search results.`);
}

return [{
  json: {
    topic: $('When Executed by Another Workflow').first().json.topic,
    topic_supported: verified.length > 0 && out.topic_supported,
    findings: verified,
    gaps,
    confidence: verified.length === 0 ? 'low' : out.confidence,
    dropped_count: dropped
  }
}];
